var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
var num = root.querySelector(".trx0-post-mem-num");
var blk = root.querySelector(".trx0-post-mem-blk");
var TOTAL = 65536, STEP = 1024, WIDTH = 24;
var timers = [], tick = null, value = 0;
function stop(){ for(var i=0;i<timers.length;i++){ clearTimeout(timers[i]); } timers=[]; if(tick){ clearInterval(tick); tick=null; } }
function later(fn,ms){ timers.push(setTimeout(fn,ms)); }
function rep(ch,n){ var s=""; while(n-- > 0){ s+=ch; } return s; }
function paint(v){
  num.textContent = String(v);
  var f = Math.round(WIDTH * v / TOTAL);
  blk.textContent = rep("█", f) + rep("░", WIDTH - f);
}
function run(){
  stop();
  root.className = "trx0-post-mem";
  value = 0; paint(0);
  tick = setInterval(function(){
    value += STEP;
    if (value >= TOTAL) { value = TOTAL; clearInterval(tick); tick = null; paint(value);
      root.classList.add("trx0-post-mem-done");
      later(function(){ root.classList.add("trx0-post-mem-p2"); }, 520);
      later(function(){ root.classList.add("trx0-post-mem-p3"); }, 1150);
      later(run, 8000);
      return; }
    paint(value);
  }, 26);
}
if (reduce) {
  paint(TOTAL);
  root.classList.add("trx0-post-mem-done");
  root.classList.add("trx0-post-mem-p2");
  root.classList.add("trx0-post-mem-p3");
} else { run(); }

