js:
var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
var out = root.querySelector(".trx0-sysbar-out");
var pc = root.querySelector(".trx0-sysbar-pc");
var net = root.querySelector(".trx0-sysbar-net");
var W = 24, INNER = W + 11;
var rows = [{k:"CPU",v:54},{k:"MEM",v:71},{k:"I/O",v:22},{k:"NET",v:38}];
var load = [1.24,0.98,0.71];
function rep(ch,n){ var s=""; while(n-- > 0){ s+=ch; } return s; }
function padEnd(s,n,c){ while(s.length<n){ s+=c; } return s; }
function padStart(s,n){ while(s.length<n){ s=" "+s; } return s; }
function two(n){ return n<10 ? "0"+n : String(n); }
function render(){
  var d = new Date();
  var time = two(d.getHours())+":"+two(d.getMinutes())+":"+two(d.getSeconds());
  var html = padEnd("┌─ SYS.MON ── "+time+" ", INNER+1, "─") + "┐\n";
  for (var i=0;i<rows.length;i++){
    var v = Math.round(rows[i].v);
    var f = Math.round(W * v / 100);
    var hot = v > 85 ? " trx0-sysbar-hot" : "";
    html += "│ " + rows[i].k + " " +
      '<span class="trx0-sysbar-f' + hot + '">' + rep("█", f) + "</span>" +
      '<span class="trx0-sysbar-e">' + rep("░", W-f) + "</span>" +
      " " + padStart(v+"%",4) + " │\n";
  }
  var lo = " LOAD "+load[0].toFixed(2)+" "+load[1].toFixed(2)+" "+load[2].toFixed(2)+" ";
  html += padEnd("└─"+lo, INNER+1, "─") + "┘";
  out.innerHTML = html;
}
function drift(){
  for (var i=0;i<rows.length;i++){
    rows[i].v += (Math.random()-0.48) * 14;
    if (rows[i].v < 4) rows[i].v = 4;
    if (rows[i].v > 99) rows[i].v = 99;
  }
  load[0] = Math.max(0.05, load[0] + (Math.random()-0.5)*0.22);
  load[1] = load[1]*0.94 + load[0]*0.06;
  load[2] = load[2]*0.98 + load[1]*0.02;
  if (pc) pc.textContent = String(190 + Math.floor(Math.random()*40));
  if (net) net.textContent = (0.4 + Math.random()*3.2).toFixed(1);
  render();
}
render();
if (!reduce) { setInterval(drift, 900); }

