var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
var log = root.querySelector(".trx0-modem-hs-log");
var leds = {
  tr: root.querySelector(".trx0-modem-hs-tr"),
  oh: root.querySelector(".trx0-modem-hs-oh"),
  cd: root.querySelector(".trx0-modem-hs-cd"),
  sd: root.querySelector(".trx0-modem-hs-sd"),
  rd: root.querySelector(".trx0-modem-hs-rd")
};
var MAX = 6;
var script = [
  {t:"ATZ", type:1, led:"tr"},
  {t:"OK", cls:"trx0-modem-hs-r", wait:280},
  {t:"ATDT9,18005550143", type:1, led:"oh"},
  {t:"DIALING . . .", cls:"trx0-modem-hs-warn", wait:520},
  {t:"RING  RING", cls:"trx0-modem-hs-warn", wait:620},
  {t:"CARRIER 33600", cls:"trx0-modem-hs-r", wait:520, led:"cd"},
  {t:"PROTOCOL: LAP-M/V42BIS", cls:"trx0-modem-hs-r", wait:340},
  {t:"CONNECT 33600/ARQ/V34", cls:"trx0-modem-hs-r", wait:340, traffic:1}
];
var timers = [], step = 0, blinker = null;
var cur = document.createElement("span");
cur.className = "trx0-modem-hs-cur";
cur.textContent = "█";
function stop(){ for(var i=0;i<timers.length;i++){ clearTimeout(timers[i]); } timers=[]; if(blinker){ clearInterval(blinker); blinker=null; } }
function later(fn,ms){ timers.push(setTimeout(fn,ms)); }
function lamp(k,on){ if(leds[k]) leds[k].classList.toggle("trx0-modem-hs-on", !!on); }
function addLine(cls){
  var d = document.createElement("div");
  d.className = "trx0-modem-hs-l" + (cls ? " " + cls : "");
  var s = document.createElement("span");
  d.appendChild(s);
  d.appendChild(cur);
  log.appendChild(d);
  while (log.children.length > MAX) { log.removeChild(log.firstChild); }
  return s;
}
function typeInto(el, txt, done){
  var i = 0;
  (function next(){
    if (i >= txt.length) { later(done, 220); return; }
    el.textContent += txt.charAt(i++);
    lamp("sd", i % 2 === 0);
    later(next, 34 + Math.random()*40);
